import {registerCardComponent, actionTypesToEvents} from "@pihanga2/core";

import {JSON_VIEWER_CARD, JSON_VIEWER_ACTION} from "./jsonViewer.types";
import {JsonViewerComponent} from "./jsonViewer.component";

export * from "./jsonViewer.types";

registerCardComponent({
  name: JSON_VIEWER_CARD,
  component: JsonViewerComponent,
  events: actionTypesToEvents(JSON_VIEWER_ACTION),
});

import React, {useLayoutEffect, useRef, useState, useCallback} from "react";
import type {PiCardProps} from "@pihanga2/core";
import {JsonView, allExpanded, defaultStyles} from "react-json-view-lite";
import {Copy, Check} from "lucide-react";
import "react-json-view-lite/dist/index.css";
import "./jsonViewer.css";

import {getIconElement} from "@/cards/icons";
import type {JsonViewerProps, JsonViewerEvents} from "./jsonViewer.types";

/**
 * Converts the `collapsed` prop (from the react-json-view API) into a
 * `shouldExpandNode` predicate for react-json-view-lite.
 *
 * - `false`  → expand everything
 * - `true`   → collapse everything
 * - number N → expand nodes at depth < N (root is depth 0)
 */
function toShouldExpandNode(
  collapsed: boolean | number | undefined,
): (level: number) => boolean {
  if (collapsed === false) return allExpanded;
  if (collapsed === true) return () => false;
  // default: collapsed = 1 → only root level expanded
  const depth = collapsed ?? 1;
  return (level: number) => level < depth;
}

/**
 * Compact, code-editor style for react-json-view-lite.
 *
 * The expand/collapse icon is positioned absolutely inside a fixed left gutter
 * (via padding-left on `.jv-basic-child`), so the opening `{` and closing `}`
 * always start at the same column — fixing the original misalignment where the
 * icon pushed the open-brace further right than the close-brace.
 */
const compactStyles = {
  // spread defaultStyles first to satisfy required fields (ariaLables, stringifyStringValues, …)
  ...defaultStyles,
  container: "jv-container",
  basicChildStyle: "jv-basic-child",
  label: "jv-label",
  clickableLabel: "jv-clickable-label",
  nullValue: "jv-null",
  undefinedValue: "jv-undefined",
  numberValue: "jv-number",
  stringValue: "jv-string",
  booleanValue: "jv-boolean",
  otherValue: "jv-other",
  punctuation: "jv-punctuation",
  expandIcon: "jv-expand-icon",
  collapseIcon: "jv-collapse-icon",
  collapsedContent: "jv-collapsed-content",
  childFieldsContainer: "jv-child-fields-container",
};

/**
 * Resolve the icon element to use for the copy button.
 *
 * Resolution order:
 *   1. `iconName` looked up in the global icon registry
 *   2. Lucide `Copy` as the built-in fallback
 */
function resolveCopyIcon(iconName?: string): React.ElementType {
  if (iconName) {
    const registered = getIconElement(iconName);
    if (registered) return registered;
  }
  return Copy;
}

/** Write `text` to the clipboard, preferring `ClipboardItem` for explicit MIME. */
async function writeToClipboard(text: string): Promise<void> {
  if (typeof ClipboardItem !== "undefined") {
    const blob = new Blob([text], {type: "text/plain"});
    await navigator.clipboard.write([new ClipboardItem({"text/plain": blob})]);
  } else {
    // Fallback for browsers without ClipboardItem support
    await navigator.clipboard.writeText(text);
  }
}

export const JsonViewerComponent = (
  props: PiCardProps<JsonViewerProps, JsonViewerEvents>,
): React.ReactNode => {
  const {
    source,
    collapsed = 1,
    modifyFn,
    style,
    className,
    cardName,
    _cls,
    copyToClipboard,
    copyIcon,
    onCopied,
  } = props;

  const elRef = useRef<HTMLDivElement>(null);
  const [copied, setCopied] = useState(false);

  useLayoutEffect(() => {
    if (modifyFn) {
      modifyFn(source, elRef.current);
    }
  }, [modifyFn, source]);

  const shouldExpandNode = toShouldExpandNode(collapsed);

  const handleCopy = useCallback(async () => {
    const text = JSON.stringify(source, null, 2);
    let success = false;
    try {
      await writeToClipboard(text);
      success = true;
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.warn("[JsonViewer] clipboard write failed:", err);
    }
    onCopied?.({success});
  }, [source, onCopied]);

  const CopyIconEl = resolveCopyIcon(copyIcon);
  const ConfirmIconEl = Check;

  return (
    <div
      className={[_cls("root", className), "jv-wrapper"].join(" ")}
      ref={elRef}
      data-pihanga={cardName}
      style={style as React.CSSProperties | undefined}
    >
      {copyToClipboard && (
        <button
          type="button"
          aria-label={copied ? "Copied!" : "Copy JSON to clipboard"}
          title={copied ? "Copied!" : "Copy JSON to clipboard"}
          className={`jv-copy-btn${copied ? " jv-copy-btn--done" : ""}`}
          onClick={handleCopy}
        >
          {copied ? (
            <ConfirmIconEl size={13} strokeWidth={2.5} />
          ) : (
            <CopyIconEl size={13} strokeWidth={2} />
          )}
        </button>
      )}
      <JsonView
        data={source as object | unknown[]}
        shouldExpandNode={shouldExpandNode}
        style={compactStyles}
        clickToExpandNode
      />
    </div>
  );
};

/*
 * jsonViewer.css — compact, code-editor style for react-json-view-lite
 *
 * Key design goals (matching the "second screenshot" style):
 *   - Monospace font, light weight (no bold keys)
 *   - Vertical guide lines via border-left on child containers
 *   - Toggle icon is absolutely positioned so { and } align on the same column
 *   - String values in green, numbers in blue, booleans in teal
 *   - Adapts to light/dark via CSS variables
 */

/* ── Wrapper (positions the copy button relative to the viewer) ─────────────── */
.jv-wrapper {
  position: relative;
}

/* ── Copy-to-clipboard button ───────────────────────────────────────────────── */
.jv-copy-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 10;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: hsl(var(--muted-foreground, 0 0% 55%));
  cursor: pointer;
  opacity: 0.35;
  transition: opacity 0.15s ease, color 0.15s ease, background 0.15s ease,
    border-color 0.15s ease;
}

/* Full opacity when the wrapper is hovered/focused-within */
.jv-wrapper:hover .jv-copy-btn,
.jv-wrapper:focus-within .jv-copy-btn {
  opacity: 1;
}

.jv-copy-btn:hover {
  color: hsl(var(--foreground));
  background: hsl(var(--muted, 0 0% 96%));
  border-color: hsl(var(--border, 0 0% 88%));
}

/* "Done" state — green check mark */
.jv-copy-btn--done {
  opacity: 1;
  color: #2e7d32;
}

.dark .jv-copy-btn--done {
  color: #81c784;
}

/* ── Container ─────────────────────────────────────────────────────────────── */
.jv-container {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 12.5px;
  font-weight: 400;
  line-height: 1.55;
  background: transparent;
  white-space: pre-wrap;
  word-wrap: break-word;
  color: var(--foreground);
}

/* ── Each row ───────────────────────────────────────────────────────────────── */
/*
 * position: relative + padding-left reserves a fixed gutter on the LEFT of
 * every row (both the "key: {" opening row AND the bare "}" closing row).
 * The toggle icon is then placed absolutely inside that gutter so it never
 * displaces the brace characters — fixing the original misalignment.
 */
.jv-basic-child {
  margin: 0;
  padding: 0 0 0 1.1em;
  position: relative;
  display: block;
}

/* ── Key labels ─────────────────────────────────────────────────────────────── */
.jv-label {
  font-weight: 400;
  color: var(--foreground);
  margin-right: 0;
}

.jv-clickable-label {
  font-weight: 400;
  color: var(--foreground);
  cursor: pointer;
  margin-right: 0;
}

.jv-clickable-label:hover {
  text-decoration: underline;
  text-decoration-style: dotted;
}

/* ── Punctuation  { } [ ] : ,  ──────────────────────────────────────────────── */
.jv-punctuation {
  color: var(--foreground);
  font-weight: 400;
}

/* ── Toggle icons — positioned in the left gutter ──────────────────────────── */
.jv-expand-icon,
.jv-collapse-icon {
  position: absolute;
  left: 0;
  /*
   * With `transform: translateY(-50%)`, `top` sets the CENTRE of the element.
   * The visual centre of the first text line = line-height / 2 = 1.55 / 2 ≈ 0.775em.
   */
  top: 0.775em;
  transform: translateY(-50%);
  width: 1em;
  font-size: 0.65em;
  line-height: 1;
  color: hsl(var(--muted-foreground, 0 0% 55%));
  user-select: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.jv-expand-icon::after {
  content: "▶";
}

.jv-collapse-icon::after {
  content: "▼";
}

/* ── Collapsed placeholder ──────────────────────────────────────────────────── */
.jv-collapsed-content {
  cursor: pointer;
  color: hsl(var(--muted-foreground, 0 0% 55%));
}

.jv-collapsed-content::after {
  content: " …";
}

/* ── Child-fields container — the vertical guide line lives here ────────────── */
.jv-child-fields-container {
  margin: 0;
  padding: 0;
  padding-left: 1.25em;
  border-left: 1px solid hsl(var(--border, 0 0% 88%));
  margin-left: 0.3em;
}

/* ── Value colours ──────────────────────────────────────────────────────────── */
.jv-null {
  color: #c0392b;
}

.jv-undefined {
  color: #c0392b;
}

.jv-string {
  color: #2e7d32;
}

/* green  — matches screenshot */
.jv-number {
  color: #1565c0;
}

/* blue */
.jv-boolean {
  color: #00796b;
}

/* teal */
.jv-other {
  color: var(--foreground);
}

/* ── Dark-mode overrides ───────────────────────────────────────────────────── */
.dark .jv-string {
  color: #81c784;
}

.dark .jv-number {
  color: #64b5f6;
}

.dark .jv-boolean {
  color: #4db6ac;
}

.dark .jv-null,
.dark .jv-undefined {
  color: #ef9a9a;
}

.dark .jv-child-fields-container {
  border-left-color: hsl(var(--border, 0 0% 25%));
}

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const JSON_VIEWER_CARD = "json-viewer";

export const JsonViewer = createCardDeclaration<
  JsonViewerProps,
  JsonViewerEvents
>(JSON_VIEWER_CARD);

export const JSON_VIEWER_ACTION = registerActions(JSON_VIEWER_CARD, [
  "clicked",
  "copied",
]);

export const onJsonViewerClicked = createOnAction<ClickedEvent>(
  JSON_VIEWER_ACTION.CLICKED,
);

export const onJsonViewerCopied = createOnAction<CopiedEvent>(
  JSON_VIEWER_ACTION.COPIED,
);

export type JsonViewerProps<S = object> = {
  /** The JSON value to display. */
  source: unknown;
  /**
   * Theme name. Maps loosely to a visual style.
   * Use "monokai", "solarized", "ocean", etc. (visual only — actual theming
   * is done via className / global CSS since react-json-view-lite uses CSS
   * variables rather than named themes).
   */
  theme?: string;
  iconStyle?: "circle" | "triangle" | "square";
  /**
   * When `true`, all nodes are collapsed.
   * When `false`, all nodes are expanded.
   * When a number N, nodes at depth >= N are collapsed (root is depth 0).
   * Default: 1 (expand root only).
   */
  collapsed?: boolean | number;
  /** When `true`, a click-to-expand interaction is enabled on node labels. */
  enableClipboard?: boolean;
  /** When `true`, removes quotes from object keys in display. */
  removeQuotesOnKeys?: boolean;
  /** When `true`, objects and arrays are labelled with their size. */
  displayObjectSize?: boolean;
  /** When `true`, data-type labels prefix values. */
  displayDataTypes?: boolean;
  /**
   * Called after the JSON is rendered, allowing post-render DOM modifications.
   * Receives the raw `source` value and the container element.
   */
  modifyFn?: ModifyFn;

  /**
   * When `true`, shows a copy-to-clipboard icon button in the top-right
   * corner of the viewer. Clicking it copies the pretty-printed JSON to the
   * clipboard using `ClipboardItem` with `text/plain` MIME type.
   */
  copyToClipboard?: boolean;

  /**
   * Icon name resolved via the global icon registry (`getIconElement`).
   * If omitted or the name is not registered, falls back to the Lucide
   * `Copy` icon automatically.
   *
   * @example
   * // Register your own icon first:
   * registerIcon("my-copy", MyCustomCopyIcon);
   * // Then pass the name to the card:
   * JsonViewer({ copyToClipboard: true, copyIcon: "my-copy", ... })
   */
  copyIcon?: string;

  /** Inline style for the react-json-view-lite container. */
  style?: S;
  /** Additional CSS class for the outer wrapper. */
  className?: string;
};

export type ModifyFn = (source: unknown, el: HTMLElement | null) => void;

export type ClickedEvent = Record<string, never>;

export type CopiedEvent = {
  /** `true` when the clipboard write succeeded, `false` on error. */
  success: boolean;
};

export type JsonViewerEvents = {
  onClicked: ClickedEvent;
  onCopied: CopiedEvent;
};
